public class BinaryToDecimal { 

	public static int binToDecimal(String binaryNumber)  
	{  
		int decimal = 0;  
		int power = 0;  
		for(int i = binaryNumber.length() - 1; i >= 0; i--)  
		{   
			if (binaryNumber.charAt(i) == '1') 
				decimal += Math.pow(2, power); 
			power++; 
		}  
		return decimal;  
	}  

