### Instruction:
Create a class in C# to calculate compound interest.

### Response:
public class CompoundInterest {
    private double principal;
    private double rate;
    private int periods;

    public CompoundInterest(double principal, double rate, int periods) {
        this.principal = principal;
        this.rate = rate;
        this.periods = periods;
    }

    public double CalculateCompoundInterest() {
        return principal * Math.Pow(1 + (rate / periods), periods);
    }
}

